import zipfile
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}

with zipfile.ZipFile('budget.xlsx') as z:
    names = z.namelist()
    print("ZIP ENTRIES:", names)

    # Load shared strings if present
    shared = []
    if 'xl/sharedStrings.xml' in names:
        root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in root.findall('m:si', NS):
            text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            shared.append(text)

    # Parse worksheet
    root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
    rows = []
    for row in root.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}row'):
        cells = {}
        for c in row.findall('m:c', NS):
            ref = c.get('r')
            t = c.get('t')
            v = c.find('m:v', NS)
            is_ = c.find('m:is', NS)
            val = None
            if v is not None:
                val = v.text
            elif is_ is not None:
                val = ''.join(t.text or '' for t in is_.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            if t == 's' and v is not None:
                val = shared[int(v.text)]
            cells[ref] = val
        if cells:
            rows.append(cells)

    for r in rows:
        print(r)
